#include "quantum.h"

void keyboard_pre_init_kb(void) {
    // Set LED IO as outputs
    gpio_set_pin_output(LED_00);
    gpio_set_pin_output(LED_01);
    gpio_set_pin_output(LED_02);
    keyboard_pre_init_user();
}

bool shutdown_kb(bool jump_to_bootloader) {
    if (!shutdown_user(jump_to_bootloader)) {
        return false;
    }
    // Shutdown LEDs
    gpio_write_pin_low(LED_00);
    gpio_write_pin_low(LED_01);
    gpio_write_pin_low(LED_02);
    return true;
}

layer_state_t layer_state_set_kb(layer_state_t state) {
    // Layer LEDs act as binary indication of current layer
    uint8_t layer = get_highest_layer(state);
    gpio_write_pin(LED_00, layer & 0b1);
    gpio_write_pin(LED_01, (layer >> 1) & 0b1);
    return layer_state_set_user(state);
}

// Optional override functions below.
// You can leave any or all of these undefined.
// These are only required if you want to perform custom actions.

void matrix_init_kb(void) {
    // put your keyboard start-up code here
    // runs once when the firmware starts up
    uint8_t led_delay_ms = 80;
    for (int i = 0; i < 2; i++) {
        gpio_write_pin_high(LED_00);
        gpio_write_pin_high(LED_01);
        gpio_write_pin_high(LED_02);
        wait_ms(led_delay_ms);
        gpio_write_pin_low(LED_00);
        gpio_write_pin_low(LED_01);
        gpio_write_pin_low(LED_02);
        if (i < 1) {
            wait_ms(led_delay_ms);
        }
    }

    matrix_init_user();
}

bool led_update_kb(led_t led_state) {
    bool res = led_update_user(led_state);
    if(res) {
        gpio_write_pin(LED_02, !led_state.num_lock);
    }
    return res;
}

bool encoder_update_kb(uint8_t index, bool clockwise) {
    if (!encoder_update_user(index, clockwise)) { return false; }

    if (index == 0) {
        switch (get_highest_layer(layer_state)) {
            case 0:
                if (clockwise) {
                    tap_code(MS_RGHT);
                } else {
                    tap_code(MS_LEFT);
                }
                break;

            default:
                if (clockwise) {
                    tap_code(KC_EQL);
                } else {
                    tap_code(KC_MINS);
                }
                break;
        }
    } else if (index == 1) {
        switch (get_highest_layer(layer_state)) {
            case 0:
                if (clockwise) {
                    tap_code(KC_VOLU);
                } else {
                    tap_code(KC_VOLD);
                }
                break;

            default:
                if (clockwise) {
                    tap_code(KC_RIGHT);
                } else {
                    tap_code(KC_LEFT);
                }
                break;
        }
    }
    return true;
}

